// 命令边界只收具名参数；未知字段、重名键和伪造资金均不得成为业务输入。
#include "resident/domains/commerce/private_shop_boundary.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool value,const char* label){++checks;if(!value)throw std::runtime_error(label);}}
int main(){try{using V=BoundaryValue;using boundary::obj;
 std::vector<PrivateShopCommand> commands={PrivateShopOpen{"premise"},PrivateShopFund{"shop",10},PrivateShopSetMarkup{"shop",500},PrivateShopRestock{"shop","grain",4,{"place","provider","role"}},PrivateShopOperate{"shop","grain"},PrivateShopCancelOperation{"action:1"},PrivateShopEmploy{"shop","policy"},PrivateShopStaffAccept{"shop","policy"},PrivateShopStaffDecision{"contract","leave"},PrivateShopRequestOrder{"shop","order.policy"},PrivateShopClose{"shop"}};
 for(const auto& command:commands){const auto kind=private_shop_command_kind(command);auto raw=encode_private_shop_command(command);auto read=decode_private_shop_command(kind,raw);check(read.ok,"decode actual typed command");check(private_shop_command_kind(read.value)==kind&&compare_boundary(raw,encode_private_shop_command(read.value)).exact(),"exact command roundtrip");auto extra=raw;extra.as<V::Dict>()->push_back({"balance",V{Integer{999}}});check(!decode_private_shop_command(kind,extra).ok,"no arbitrary balance setter");auto duplicate=raw;duplicate.as<V::Dict>()->push_back(duplicate.as<V::Dict>()->front());check(!decode_private_shop_command(kind,duplicate).ok,"duplicate command field rejected");}
 check(!decode_private_shop_command("private_shop_open",obj({{"premises_id",V{StableId{}}}})).ok,"empty ID rejected");check(!decode_private_shop_command("private_shop_fund",obj({{"shop_id",V{"shop"}},{"amount",V{Integer{0}}}})).ok,"zero capital rejected");check(!decode_private_shop_command("private_shop_fund",obj({{"shop_id",V{"shop"}},{"amount",V{"10"}}})).ok,"string amount rejected");check(!decode_private_shop_command("private_shop_set_markup",obj({{"shop_id",V{"shop"}},{"markup_basis_points",V{Integer{250}}}})).ok,"noncanonical markup rejected");check(!decode_private_shop_command("private_shop_staff_decide",obj({{"contract_id",V{"contract"}},{"decision",V{"paid"}}})).ok,"cannot forge payment decision");check(!decode_private_shop_command("private_shop_unknown",obj({})).ok,"unknown command rejected");auto restock=encode_private_shop_command(commands[3]);for(auto& row:*restock.as<V::Dict>())if(row.first=="context")row.second.as<V::Dict>()->push_back({"role_id",V{"other"}});check(!decode_private_shop_command("private_shop_restock",restock).ok,"nested duplicate contact rejected");
 std::cout<<checks<<"/0 private shop command checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
